from contextlib import contextmanager

def retry_read(read: Callable[[Any], Any], attempts: int) -> Optional[Any]:
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    @contextmanager
    def retry():
        for attempt in range(attempts):
            try:
                return yield from read()
            except TimeoutError:
                pass
        raise TimeoutError("all attempts timed out")

    return retry().__next__()

