from typing import List, Dict, Any

def render_row(fields: List[str], record: Dict[str, Any], missing: str = "-") -> str:
    def escape(value: Any) -> str:
        if value is None:
            return missing
        if isinstance(value, bool):
            return str(value).lower()
        if isinstance(value, str):
            value = value.replace("\\", "\\\\")
            value = value.replace("\t", "\\t")
            value = value.replace("\n", "\\n")
        return str(value)

    escaped_fields = [escape(field) for field in fields]
    escaped_record = {field: escape(record.get(field, missing)) for field in fields}
    return "\t".join(escaped_record.values())

def write_all(write, data):
    total_written = 0
    while data:
        consumed = write(data)
        if consumed == 0:
            raise OSError("write returned zero")
        if consumed < 0:
            raise OSError("write returned a negative number")
        if consumed > len(data):
            raise OSError("write returned a count larger than the offered slice")
        total_written += consumed
        data = data[consumed:]
    return total_written

def coerce_field(value):
    if value is None:
        return None
    elif isinstance(value, bool):
        return 'true' if value else 'false'
    elif isinstance(value, str):
        return value.strip()
    elif isinstance(value, (int, float)):
        return str(value)
    else:
        raise TypeError("Unsupported type for coercion")

def total_coverage(spans):
    if not spans:
        return 0

    spans.sort()
    start = spans[0][0]
    end = spans[0][1]
    count = 0

    for span in spans[1:]:
        if span[0] <= end:
            end = max(end, span[1])
        else:
            count += end - start + 1
            start = span[0]
            end = span[1]

    count += end - start + 1

    return count

def ttl_lookup(cache, key, now, fetch, ttl):
    if key not in cache:
        return None
    expires_at, value = cache[key]
    if expires_at <= now:
        return fetch(key)
    return value

