def select_manifest(root):
    return sorted([p.relative_to(root) for p in root.rglob('*.manifest') if not p.is_dir()])

def first_unique(values, count):
    if count <= 0:
        return []
    seen = set()
    result = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
            if len(result) == count:
                break
    return result

def encode_frame(payload):
    if len(payload) > 65535:
        raise ValueError("Payload length exceeds maximum allowed size")
    return payload[:2].to_bytes(2, byteorder='big') + payload[2:]

from datetime import datetime

def wait_microseconds(start, end):
    if not isinstance(start, datetime) or not isinstance(end, datetime):
        raise ValueError("Both inputs must be datetime objects")
    if start > end:
        raise ValueError("Start datetime must be before end datetime")
    delta = end - start
    return delta.total_seconds() * 1000000

